import { randomUUID } from 'expo-crypto';
import { router } from 'expo-router';
import { useSetAtom } from 'jotai';
import { useEffect, useRef, useState } from 'react';

import { queryKeys, useToken } from '@/api/queries';
import { queryClient, signOut } from '@/api/query-client';
import { createClaim } from '@/api/claims';
import {
  loadSubmission,
  saveSubmission,
  submitWithRetry,
  type ClaimSubmission,
} from '@/lib/claim-submit';
import { addPendingClaimAtom } from '@/state/pendingClaims';

export type Phase = 'edit' | 'review' | 'submitting' | 'unknown';
export type ServerError = { field?: string; message: string };

export function useClaimSubmission(asset: string) {
  const token = useToken();
  const addPendingClaim = useSetAtom(addPendingClaimAtom);
  const [phase, setPhase] = useState<Phase>('edit');
  const [serverError, setServerError] = useState<ServerError | null>(null);
  // Resume an unresolved submission (e.g. after a reload) instead of letting the user claim again.
  const [submission, setSubmission] = useState<ClaimSubmission | null>(() => {
    const s = loadSubmission();
    return s?.body.asset === asset ? s : null;
  });
  const running = useRef(false);

  async function run(sub: ClaimSubmission) {
    if (running.current) return; // no double submit
    running.current = true;
    setPhase('submitting');
    setServerError(null);
    const result = await submitWithRetry(sub, (s) => createClaim(token, s.body, s.key));
    running.current = false;

    if (result.kind === 'created') {
      const { claim } = result;
      saveSubmission(null);
      addPendingClaim({
        claimId: claim.id,
        asset: claim.asset,
        amount: claim.amount,
        createdAt: claim.createdAt,
      });
      queryClient.setQueryData(queryKeys.claim(claim.id), claim);
      router.replace({ pathname: '/claims/[id]', params: { id: claim.id } });
    } else if (result.kind === 'rejected') {
      // The server answered and created nothing: safe to forget the key.
      saveSubmission(null);
      setSubmission(null);
      const e = result.error;
      if (e.isUnauthorized) return signOut('Your token was rejected or has expired. Enter a valid token.');
      setServerError({
        field: e.field,
        message:
          e.code === 'IDEMPOTENCY_MISMATCH'
            ? 'This claim conflicted with an earlier request. Check your activity before trying again.'
            : e.message,
      });
      setPhase('edit');
    } else {
      setPhase('unknown');
    }
  }

  useEffect(() => {
    // One-off resume on mount; run() starts with setPhase, which is the point.
    // eslint-disable-next-line react-hooks/set-state-in-effect
    if (submission) void run(submission);
    // eslint-disable-next-line react-hooks/exhaustive-deps -- once on mount
  }, []);

  function confirm(amount: string, destinationId: string) {
    if (running.current) return;
    const sub: ClaimSubmission = { key: randomUUID(), body: { asset, amount, destinationId } };
    saveSubmission(sub); // before sending, so a reload mid-request resumes with this key
    setSubmission(sub);
    void run(sub);
  }

  return {
    phase,
    setPhase,
    serverError,
    setServerError,
    persisted: submission ?? loadSubmission(),
    retry: () => submission && run(submission),
    confirm,
  };
}

import { useQuery } from '@tanstack/react-query';
import { useAtomValue } from 'jotai';
import { useState } from 'react';

import { getClaimOptions } from '@/api/claim-options';
import { queryKeys, useBalances, useToken } from '@/api/queries';
import { formatAmount, validateClaimAmount, type ClaimAmountError } from '@/lib/amount';
import { applyPendingClaims, pendingClaimsAtom } from '@/state/pendingClaims';

import type { ServerError } from './use-claim-submission';

export type ClaimFormState = NonNullable<ReturnType<typeof useClaimForm>['form']>;

export function useClaimForm(
  asset: string,
  serverError: ServerError | null,
  setServerError: (e: null) => void,
) {
  const token = useToken();
  const balances = useBalances();
  const pendingClaims = useAtomValue(pendingClaimsAtom);
  const options = useQuery({
    queryKey: queryKeys.claimOptions(asset),
    queryFn: ({ signal }) => getClaimOptions(token, asset, signal),
  });
  const [amount, setAmount] = useState('');
  const [destinationId, setDestinationId] = useState<string | null>(null);

  const load = {
    loading: options.isPending || balances.isPending,
    message: options.error?.message ?? balances.error?.message ?? `No ${asset} balance.`,
    onRetry: () => {
      void options.refetch();
      void balances.refetch();
    },
  };
  const rawBalance = balances.data?.items.find((b) => b.asset === asset);
  if (!options.data || !balances.data || !rawBalance) return { load, form: null };

  const [balance] = applyPendingClaims([rawBalance], balances.data.asOf, pendingClaims);
  const { decimals } = balance;
  const opts = options.data;
  const fmt = (v: Parameters<typeof formatAmount>[0]) => `${formatAmount(v, decimals)} ${asset}`;
  const destination = opts.destinations.find((d) => d.id === destinationId) ?? opts.destinations[0];
  const validation = validateClaimAmount({
    input: amount,
    decimals,
    minAmount: opts.minAmount,
    available: balance.available,
    fee: opts.fee,
  });
  const amountError =
    serverError?.field === 'amount'
      ? serverError.message
      : !validation.ok
        ? errorText(validation.error, decimals, fmt(opts.minAmount), fmt(opts.fee))
        : null;

  return {
    load,
    form: {
      amount,
      balance,
      opts,
      fmt,
      destination,
      validation,
      amountError,
      formError: serverError && serverError.field !== 'amount' ? serverError.message : null,
      canReview: validation.ok && !!destination && serverError?.field !== 'amount',
      // Some locales' decimal pads type "," as the separator.
      changeAmount: (t: string) => {
        setAmount(t.replace(',', '.'));
        setServerError(null);
      },
      setMax: () => {
        setAmount(balance.available);
        setServerError(null);
      },
      setDestinationId,
    },
  };
}

function errorText(error: ClaimAmountError, decimals: number, min: string, fee: string): string {
  switch (error) {
    case 'empty':
      return 'Enter an amount.';
    case 'format':
      return 'Enter a number like 0.5.';
    case 'too_many_decimals':
      return `At most ${decimals} decimal places.`;
    case 'below_min':
      return `Minimum is ${min}.`;
    case 'above_available':
      return 'More than your available balance.';
    case 'not_above_fee':
      return `Must be more than the fee (${fee}).`;
  }
}

import { useQuery } from '@tanstack/react-query';
import { useSetAtom } from 'jotai';
import { useEffect } from 'react';

import { getClaim } from '@/api/claims';
import { queryKeys, useBalances, useToken } from '@/api/queries';
import { queryClient } from '@/api/query-client';
import { removePendingClaimAtom } from '@/state/pendingClaims';

const POLL_MS = 2000;

export function useClaimStatus(id: string) {
  const token = useToken();
  const removePendingClaim = useSetAtom(removePendingClaimAtom);
  const balances = useBalances();
  const claim = useQuery({
    queryKey: queryKeys.claim(id),
    queryFn: ({ signal }) => getClaim(token, id, signal),
    refetchInterval: (q) => (q.state.data?.status === 'pending' ? POLL_MS : false),
  });
  const status = claim.data?.status;

  useEffect(() => {
    if (status !== 'completed' && status !== 'failed') return;
    // Failed: the amount is available again. Completed stays in the overlay until a snapshot includes it.
    if (status === 'failed') removePendingClaim(id);
    void queryClient.invalidateQueries({ queryKey: queryKeys.balances });
    void queryClient.invalidateQueries({ queryKey: queryKeys.activity });
  }, [status, id, removePendingClaim]);

  // Decimals come from balances; until they load, show the server's strings as-is.
  const decimals = balances.data?.items.find((b) => b.asset === claim.data?.asset)?.decimals;
  return { claim, decimals };
}

import { ActivityIndicator, Pressable, Text, View } from 'react-native';

import { Colors } from '@/constants/theme';

import { styles } from './ui';

export function LoadState({
  loading,
  message,
  onRetry,
}: {
  loading: boolean;
  message: string;
  onRetry: () => void;
}) {
  return (
    <View style={styles.center}>
      {loading ? (
        <ActivityIndicator size="large" color={Colors.primary} />
      ) : (
        <>
          <Text style={styles.text}>{message}</Text>
          <Pressable accessibilityRole="button" style={styles.button} onPress={onRetry}>
            <Text style={styles.buttonText}>Retry</Text>
          </Pressable>
        </>
      )}
    </View>
  );
}

import { Link } from 'expo-router';
import { ActivityIndicator, Pressable, Text, View } from 'react-native';

import { Colors } from '@/constants/theme';

import { styles } from './ui';

export function OtherClaimPending({ asset }: { asset: string }) {
  return (
    <View style={styles.center}>
      <Text style={styles.text}>Your {asset} claim is still being confirmed. Finish it first.</Text>
      <Link href={{ pathname: '/claim/[asset]', params: { asset } }} style={styles.link}>
        Go to {asset} claim
      </Link>
    </View>
  );
}

export function SubmissionState({
  phase,
  onRetry,
}: {
  phase: 'submitting' | 'unknown';
  onRetry: () => void;
}) {
  return (
    <View style={styles.center}>
      {phase === 'submitting' ? (
        <>
          <ActivityIndicator size="large" color={Colors.primary} />
          <Text style={styles.text}>Checking claim status…</Text>
        </>
      ) : (
        <>
          <Text style={[styles.text, styles.error]} accessibilityRole="alert">
            We couldn&apos;t confirm your claim. Don&apos;t claim again — tap Retry check.
          </Text>
          <Pressable accessibilityRole="button" style={styles.button} onPress={onRetry}>
            <Text style={styles.buttonText}>Retry check</Text>
          </Pressable>
        </>
      )}
    </View>
  );
}

import { Pressable, ScrollView, Text } from 'react-native';

import { Row, styles } from './ui';

export function ClaimReview({
  asset,
  amount,
  fee,
  receive,
  destination,
  onConfirm,
  onEdit,
}: {
  asset: string;
  amount: string;
  fee: string;
  receive: string;
  destination: string;
  onConfirm: () => void;
  onEdit: () => void;
}) {
  return (
    <ScrollView style={styles.screen} contentContainerStyle={styles.content}>
      <Text style={styles.title}>Review claim</Text>
      <Row label="Asset" value={asset} />
      <Row label="Amount" value={amount} />
      <Row label="Fee" value={fee} />
      <Row label="You receive" value={receive} strong />
      <Row label="Destination" value={destination} />
      <Pressable accessibilityRole="button" style={styles.button} onPress={onConfirm}>
        <Text style={styles.buttonText}>Confirm</Text>
      </Pressable>
      <Pressable accessibilityRole="button" onPress={onEdit} hitSlop={8}>
        <Text style={[styles.link, styles.centerText]}>Edit</Text>
      </Pressable>
    </ScrollView>
  );
}

import { Pressable, ScrollView, Text, TextInput, View } from 'react-native';

import type { ClaimFormState } from '@/hooks/use-claim-form';

import { Row, styles } from './ui';

export function ClaimForm({
  asset,
  form,
  onReview,
}: {
  asset: string;
  form: ClaimFormState;
  onReview: () => void;
}) {
  const { amount, balance, opts, fmt, destination, validation, amountError, formError } = form;
  return (
    <ScrollView style={styles.screen} contentContainerStyle={styles.content} keyboardShouldPersistTaps="handled">
      <Row label="Available" value={fmt(balance.available)} strong />
      <Row label="Minimum" value={fmt(opts.minAmount)} />
      <Row label="Fee" value={fmt(opts.fee)} />

      <Text style={styles.label}>Amount</Text>
      <View style={styles.inputRow}>
        <TextInput
          style={styles.input}
          value={amount}
          onChangeText={form.changeAmount}
          keyboardType="decimal-pad"
          placeholder="0.00"
          accessibilityLabel={`Amount in ${asset}`}
          autoCorrect={false}
        />
        <Pressable accessibilityRole="button" onPress={form.setMax} style={styles.maxButton}>
          <Text style={styles.link}>Max</Text>
        </Pressable>
      </View>
      {amount !== '' && amountError && (
        <Text style={styles.error} accessibilityRole="alert">
          {amountError}
        </Text>
      )}
      {validation.ok && <Row label="You receive" value={fmt(validation.receive)} strong />}

      <Text style={styles.label}>Destination</Text>
      {opts.destinations.length > 1 ? (
        opts.destinations.map((d) => (
          <Pressable
            key={d.id}
            accessibilityRole="radio"
            accessibilityState={{ checked: d.id === destination?.id }}
            onPress={() => form.setDestinationId(d.id)}
            style={[styles.option, d.id === destination?.id && styles.optionSelected]}>
            <Text style={styles.text}>{d.label}</Text>
          </Pressable>
        ))
      ) : (
        <Text style={styles.text}>{destination?.label ?? 'No destination available'}</Text>
      )}

      {formError && (
        <Text style={styles.error} accessibilityRole="alert">
          {formError}
        </Text>
      )}
      <Pressable
        accessibilityRole="button"
        disabled={!form.canReview}
        style={[styles.button, !form.canReview && styles.disabled]}
        onPress={onReview}>
        <Text style={styles.buttonText}>Review</Text>
      </Pressable>
    </ScrollView>
  );
}

import { Link } from 'expo-router';
import { ActivityIndicator, ScrollView, Text, View } from 'react-native';

import type { Claim } from '@/api/types';
import { Colors } from '@/constants/theme';
import { formatAmount } from '@/lib/amount';

import { Row, styles } from './ui';

export function ClaimStatusCard({
  claim: c,
  decimals,
  refreshFailed,
}: {
  claim: Claim;
  decimals: number | undefined;
  refreshFailed: boolean;
}) {
  const fmt = (v: string) => `${decimals == null ? v : formatAmount(v, decimals)} ${c.asset}`;
  const statusColor =
    c.status === 'completed' ? Colors.success : c.status === 'failed' ? Colors.danger : Colors.warning;

  return (
    <ScrollView style={styles.screen} contentContainerStyle={styles.content}>
      <View style={styles.row}>
        <Text style={styles.title}>{c.asset} claim</Text>
        {c.status === 'pending' && <ActivityIndicator color={Colors.primary} />}
      </View>
      <Text style={[styles.title, { color: statusColor }]} accessibilityLiveRegion="polite">
        {c.status === 'pending' ? 'Pending…' : c.status === 'completed' ? 'Completed' : 'Failed'}
      </Text>
      {c.status === 'failed' && (
        <Text style={styles.error} accessibilityRole="alert">
          {c.failureReason ?? 'The claim failed.'} The amount is back in your available balance.
        </Text>
      )}
      <Row label="Amount" value={fmt(c.amount)} />
      <Row label="Fee" value={fmt(c.fee)} />
      <Row label="You receive" value={fmt(c.receiveAmount)} strong />
      <Row label="Claim ID" value={c.id} />
      {refreshFailed && <Text style={styles.error}>Couldn&apos;t refresh the status. Retrying…</Text>}
      <Link href="/" replace style={[styles.link, styles.centerText]}>
        Back to balances
      </Link>
    </ScrollView>
  );
}

import { Stack, useLocalSearchParams } from 'expo-router';

import { LoadState } from '@/components/claim/load-state';
import { ClaimStatusCard } from '@/components/claim/status-card';
import { useClaimStatus } from '@/hooks/use-claim-status';

export default function ClaimStatusScreen() {
  const { id } = useLocalSearchParams<{ id: string }>();
  const { claim, decimals } = useClaimStatus(id);

  return (
    <>
      <Stack.Screen options={{ title: 'Claim status' }} />
      {claim.data ? (
        <ClaimStatusCard claim={claim.data} decimals={decimals} refreshFailed={claim.isError} />
      ) : (
        <LoadState
          loading={claim.isPending}
          message={claim.error?.message ?? 'Could not load the claim.'}
          onRetry={() => claim.refetch()}
        />
      )}
    </>
  );
}

